function getAntenna(frequency, transmitting) {
  const antennas = [
    { rx: 'vertical',   tx: 'vertical',   min: 1.8,    max: 2.0 },
    { rx: 'vertical',   tx: 'fandipole',  min: 3.5,    max: 4.0 },
    { rx: 'vertical',   tx: 'fandipole',  min: 5.3305, max: 5.405 },
    { rx: 'vertical',   tx: 'fandipole',  min: 7.0,    max: 7.3 },
    { rx: 'deltaloop',  tx: 'deltaloop',  min: 10.1,   max: 10.15 },
    { rx: 'vertical',   tx: 'fandipole',  min: 14.0,   max: 14.35 },
    { rx: 'vertical',   tx: 'fandipole',  min: 18.068, max: 18.168 },
    { rx: 'deltaloop',  tx: 'deltaloop',  min: 21.0,   max: 21.45 },
    { rx: 'deltaloop',  tx: 'deltaloop',  min: 24.89,  max: 24.99 },
    { rx: 'deltaloop',  tx: 'deltaloop',  min: 28.0,   max: 29.7 }
  ];

  const band = antennas.find(
    b => Number(frequency)/1000000 >= b.min
      && Number(frequency)/1000000 <= b.max);

  if (!band) {
    return 'deltaloop';
  }

  return transmitting ? band.tx : band.rx;
}

// msg.payload is 'ptt', 'band' or 'force'
const followBands = flow.get('followBands');
const frequency = (flow.get('frequency'));
const txA = (flow.get('txAntenna') || 'deltaloop').toString();
const rxA = (flow.get('rxAntenna') || 'deltaloop').toString();
const transmitting = flow.get('wsjtxTransmitting') === true;
const out = [];

// Manual force always wins over automatic band following
if (msg.payload === 'force'){
    if (followBands && frequency) {
        out.push({payload:true, topic: getAntenna(frequency, transmitting)});
        return out;
    }
    out.push({payload:true, topic: txA});
    out.push({payload:true, topic: rxA});
    return out;
}

// Follow-bands update from WSJT-X status messages
if (msg.payload === 'band') {
    const bandFrequency = (msg.frequency !== undefined) ? msg.frequency : frequency;
    const bandTransmitting = (msg.transmitting !== undefined) ? msg.transmitting === true : transmitting;
    if (followBands && bandFrequency) {
        out.push({payload:true, topic: getAntenna(bandFrequency, bandTransmitting)});
    }
    return out;
}

// PTT based sequencing
if (msg.payload === 'ptt') {
    const eventFrequency = (msg.frequency !== undefined) ? msg.frequency : frequency;
    const eventTransmitting = msg.transmitting === true;
    const antenna = (followBands && eventFrequency)
        ? getAntenna(eventFrequency, eventTransmitting)
        : (eventTransmitting ? txA : rxA);
    out.push({payload:true, topic: antenna});
    return out;
}

return out;

// Only pass messages for vertical
if(msg.topic === 'vertical'){
    return [{payload: false}, {payload: true}]; // first = Invert, second = Relay
} else { return null; }

// Only pass messages for fandipole
if(msg.topic === 'fandipole'){
    return [{payload: false}, {payload: true}];
} else { return null; }

// Only pass messages for deltaloop
node.log("deltaloop: " + msg);
if(msg.topic === 'deltaloop'){

    return [{payload: false}, {payload: true}, {payload: msg.payload}];
} else { return null; }

flow.set('rxAntenna', msg.payload);
node.status({fill:"green", shape:"dot", text:"RX="+msg.payload});
return {payload:"RX antenna set to "+msg.payload};

flow.set('txAntenna', msg.payload);
node.status({fill:"blue", shape:"dot", text:"TX="+msg.payload});
return {payload:"TX antenna set to "+msg.payload};

if (msg.payload.type === 'status') {
    const mode = String(msg.payload.mode || '').trim().toUpperCase();

    flow.set('wsjtxMode', mode);
    msg.mode = mode;
    msg.payload = msg.payload.freqency;

    node.status({
        fill: "green",
        shape: "dot",
        text: "mode=" + (mode || "?")
    });
    return msg;
}
return null;

flow.set('followBands', msg.payload);
flow.set('wsjtxBandFrequency', null);
flow.set('wsjtxTransmitting', null);
node.status({fill:"yellow", shape:"dot", text:"followBands="+msg.payload});
return {payload:"followBands set to "+msg.payload};

flow.set('frequency', msg.payload);
node.status({fill:"yellow", shape:"dot", text:"frequency="+msg.payload});
return {payload:"frequency set to "+msg.payload};

if (msg.payload.type !== 'status') {
    return null;
}

const transmitting = msg.payload.transmitting === true;
const frequency = msg.payload.freqency;
const followBands = flow.get('followBands');

const previousTransmitting = flow.get('wsjtxTransmitting');
const transmittingChanged = previousTransmitting === undefined
    || previousTransmitting === null
    || previousTransmitting !== transmitting;
flow.set('wsjtxTransmitting', transmitting);

if (followBands) {
    const previousFrequency = flow.get('wsjtxBandFrequency');
    const frequencyChanged = frequency !== undefined
        && (previousFrequency === undefined || previousFrequency === null || previousFrequency !== frequency);
    flow.set('wsjtxBandFrequency', frequency);

    if (frequencyChanged || transmittingChanged) {
        return {
            payload: 'band',
            frequency: frequency,
            transmitting: transmitting,
            mode: msg.payload.mode
        };
    }
    return null;
}

flow.set('wsjtxBandFrequency', null);

if (!transmittingChanged) {
    return null;
}

return {
    payload: 'ptt',
    transmitting: transmitting,
    frequency: frequency,
    mode: msg.payload.mode
};
